import{_ as c,r as e,o as i,c as r,e as s,a as t,d as a,s as p}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"Content Blocks - October CMS - 2.x","titleTemplate":false,"description":"","frontmatter":{},"headers":[{"level":2,"title":"Introduction","slug":"introduction","link":"#introduction","children":[]},{"level":2,"title":"Rendering Content Blocks","slug":"rendering-content-blocks","link":"#rendering-content-blocks","children":[]},{"level":2,"title":"Passing Variables to Content Blocks","slug":"passing-variables-to-content-blocks","link":"#passing-variables-to-content-blocks","children":[{"level":3,"title":"Global Variables","slug":"global-variables","link":"#global-variables","children":[]}]}],"relativePath":"2.x/cms/content.md","filePath":"2.x/cms/content.md"}'),d={name:"2.x/cms/content.md"};function g(u,n,h,k,m,b){const o=e("pre-heading"),l=e("post-heading");return i(),r("div",null,[s(o),n[0]||(n[0]=t("h1",null,"Content Blocks",-1)),s(l),n[1]||(n[1]=t("p",null,[a("Content Blocks can be text, HTML or "),t("a",{href:"http://daringfireball.net/projects/markdown/syntax",target:"_blank",rel:"noopener noreferrer",class:"is-ext"},[a("Markdown"),t("span",null,[t("svg",{xmlns:"http://www.w3.org/2000/svg","aria-hidden":"true",focusable:"false",x:"0px",y:"0px",viewBox:"0 0 100 100",width:"15",height:"15",class:"icon outbound"},[t("path",{fill:"currentColor",d:"M18.8,85.1h56l0,0c2.2,0,4-1.8,4-4v-32h-8v28h-48v-48h28v-8h-32l0,0c-2.2,0-4,1.8-4,4v56C14.8,83.3,16.6,85.1,18.8,85.1z"}),a(),t("polygon",{fill:"currentColor",points:"45.7,48.7 51.3,54.3 77.2,28.5 77.2,37.2 85.2,37.2 85.2,14.9 62.8,14.9 62.8,22.9 71.5,22.9"})]),a(),t("span",{class:"sr-only"},"(opens new window)")])]),a(" blocks that are edited separately from the page or layout. They're designed to hold static content only and support basic templating variables. "),t("a",{href:"./partials.html"},"Partials"),a(" are more flexible and should be used for generating dynamic content.")],-1)),n[2]||(n[2]=p(`<h2 id="introduction"><a href="#introduction" class="header-anchor">#</a> Introduction</h2><p>Content blocks files reside in the <strong>/content</strong> subdirectory of a theme directory. The following extensions are supported for content files.</p><div class="table"><table tabindex="0"><thead><tr><th>Extension</th><th>Description</th></tr></thead><tbody><tr><td><strong>htm</strong></td><td>Used for HTML markup.</td></tr><tr><td><strong>txt</strong></td><td>Used for plain text.</td></tr><tr><td><strong>md</strong></td><td>Used for Markdown syntax.</td></tr></tbody></table></div><p>The extension affects a content block&#39;s display mode in the back-end user interface, either with a WYSIWYG editor, plain text editor or markdown editor. It also determines rendering the blocks on the website; for example, Markdown blocks will convert to HTML before display.</p><h2 id="rendering-content-blocks"><a href="#rendering-content-blocks" class="header-anchor">#</a> Rendering Content Blocks</h2><p>Use the <code>{% content &#39;file.htm&#39; %}</code> tag to render a content block in a <a href="./pages.html">page</a>, <a href="./partials.html">partial</a> or <a href="./layouts.html">layout</a>.</p><p>This example shows a complete page rendering a content block.</p><div class="language-twig extra-class"><pre class="language-twig"><code>url = &quot;/contacts&quot;
==
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>contacts<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>contacts.htm<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Another example rendering some markdown with the <code>md</code> extension.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>my-markdown.md<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p><a id="oc-passing-variables-to-content-blocks"></a></p><h2 id="passing-variables-to-content-blocks"><a href="#passing-variables-to-content-blocks" class="header-anchor">#</a> Passing Variables to Content Blocks</h2><p>Sometimes you may need to pass variables to a content block from the external code. While content blocks do not support Twig markup, they do support using variables with basic syntax. You can pass variables to content blocks by specifying them after the content block name in the <code>{% content %}</code> tag.</p><p>Passing the variable called <code>name</code> with a value <strong>John</strong> to the content block.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">content</span> <span class="token string"><span class="token punctuation">&#39;</span>welcome.htm<span class="token punctuation">&#39;</span></span> name<span class="token operator">=</span><span class="token string"><span class="token punctuation">&#39;</span>John<span class="token punctuation">&#39;</span></span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Inside the content block, variables can be accessed using singular <em>curly brackets</em>.</p><div class="language- extra-class"><pre class="language-text"><code>&lt;h1&gt;This is a demo for {name}&lt;/h1&gt;
</code></pre></div><blockquote><p><strong>Tip</strong>: More information on variable use can be found <a href="./../markup/tag-content.html">in the Markup guide</a>.</p></blockquote><h3 id="global-variables"><a href="#global-variables" class="header-anchor">#</a> Global Variables</h3><p>You may register variables that are globally available to all content blocks with the <code>View::share</code> method.</p><div class="language-php extra-class"><pre class="language-php"><code><span class="token class-name static-context">View</span><span class="token operator">::</span><span class="token function">share</span><span class="token punctuation">(</span><span class="token string single-quoted-string">&#39;site_name&#39;</span><span class="token punctuation">,</span> <span class="token string single-quoted-string">&#39;October CMS&#39;</span><span class="token punctuation">)</span><span class="token punctuation">;</span>
</code></pre></div><p>A common area to place this method is inside the register or boot method of a <a href="./../plugin/registration.html">plugin registration file</a>. Using the above example, the variable <code>{site_name}</code> will be available inside all content blocks.</p><div class="language- extra-class"><pre class="language-text"><code>&lt;p&gt;Welcome to {site_name}&lt;/p&gt;
</code></pre></div>`,23))])}const w=c(d,[["render",g]]);export{f as __pageData,w as default};
